insert into kafaa_wfn_offers (id, strand, sort, status, seats, weeks, months, closes_on, focus, title_en, title_ar, host_en, host_ar, placement_en, placement_ar) values
('wo-visit-twin', 'visiting', 10, 'open', 2, 6, null, '2026-11-30', array['ai_data','digital_plant']::text[], 'Visiting placement: digital twin team at a partner utility (concept)', 'تنسيب زائر: فريق التوأم الرقمي لدى مرفق شريك (مفهوم)', 'International nuclear operator partner (concept)', 'مشغّل نووي دولي شريك (مفهوم)', 'Six weeks validating a plant model with the partner''s twin team.', 'ستة أسابيع في التحقق من نموذج محطة مع فريق التوأم الرقمي لدى الشريك.'),
('wo-visit-smr', 'visiting', 20, 'open', 2, 8, null, '2026-12-15', array['advanced_reactor']::text[], 'Visiting placement: SMR design review team (concept, no deployment decision implied)', 'تنسيب زائر: فريق مراجعة تصميم مفاعل صغير (مفهوم، لا يُفهم منه أي قرار نشر)', 'Advanced-reactor vendor partner (concept)', 'مورّد مفاعلات متقدمة شريك (مفهوم)', 'Eight weeks observing design reviews and passive-safety analysis.', 'ثمانية أسابيع لمتابعة مراجعات التصميم وتحليل السلامة السلبية.'),
('wo-visit-hub', 'visiting', 30, 'closed', 1, 4, null, '2026-09-15', array['leadership']::text[], 'Visiting placement: international knowledge hub (concept)', 'تنسيب زائر: مركز معرفة دولي (مفهوم)', 'International organisation partner (concept)', 'منظمة دولية شريكة (مفهوم)', 'Four weeks with a knowledge-management team.', 'أربعة أسابيع مع فريق لإدارة المعرفة.'),
('wo-study-ntm', 'sponsored', 40, 'open', 2, null, 24, '2027-01-31', array['leadership','project_delivery']::text[], 'Sponsored master''s in nuclear technology management, with a placement (concept)', 'ماجستير مموّل في إدارة التكنولوجيا النووية مع تنسيب (مفهوم)', 'INMA-endorsed university (concept)', 'جامعة معتمدة من INMA (مفهوم)', 'A three-month placement in an ENEC project team during the second year.', 'تنسيب لمدة ثلاثة أشهر في فريق مشاريع بالمؤسسة خلال السنة الثانية.'),
('wo-study-data', 'sponsored', 50, 'open', 2, null, 18, '2027-01-31', array['ai_data']::text[], 'Sponsored master''s in data science for engineering, with a placement (concept)', 'ماجستير مموّل في علوم البيانات للهندسة مع تنسيب (مفهوم)', 'UAE university partner (concept)', 'جامعة شريكة في الدولة (مفهوم)', 'A three-month placement with the plant data and AI team.', 'تنسيب لمدة ثلاثة أشهر مع فريق بيانات المحطة والذكاء الاصطناعي.'),
('wo-study-h2', 'sponsored', 60, 'open', 1, null, 12, '2026-12-31', array['green_energy']::text[], 'Sponsored postgraduate certificate in hydrogen and energy systems, with a placement (concept)', 'شهادة دراسات عليا مموّلة في الهيدروجين وأنظمة الطاقة مع تنسيب (مفهوم)', 'UAE university partner (concept)', 'جامعة شريكة في الدولة (مفهوم)', 'Six weeks with the energy-transition team on a process-heat study.', 'ستة أسابيع مع فريق تحوّل الطاقة في دراسة للحرارة الصناعية.')
